async (page) => {
          const url = 'https://google.com';
          const start = Date.now();
          let firstAttemptOk = false;
          let status = 'Down';
          let httpCode = null;
          let diagnosis = 'Unknown error';
          let duration = 0;

          // 1. First attempt: standard page.goto with a real User-Agent
          try {
            await page.setExtraHTTPHeaders({
              'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
            });
            const res = await page.goto(url, { timeout: 10000, waitUntil: 'domcontentloaded' });
            duration = Date.now() - start;
            if (res) {
              firstAttemptOk = true;
              httpCode = res.status();
              status = httpCode >= 500 ? 'Down' : (httpCode >= 400 ? 'Degraded' : 'Up');
              diagnosis = httpCode >= 500 ? '5xx Server Error' : (httpCode >= 400 ? 'Client Error' : 'All systems operational');
            }
          } catch (err) {
            const msg = err.message || '';
            if (msg.includes('ERR_NAME_NOT_RESOLVED')) {
              diagnosis = 'DNS failure';
            } else if (msg.includes('ERR_CERT_DATE_INVALID') || msg.includes('ERR_CERT_COMMON_NAME_INVALID') || msg.includes('ERR_CERT_AUTHORITY_INVALID') || msg.includes('certificate') || msg.includes('SSL')) {
              diagnosis = 'SSL expired';
            } else if (msg.includes('timeout') || msg.includes('Timeout') || msg.includes('ERR_CONNECTION_TIMED_OUT')) {
              diagnosis = 'timeout';
            } else if (msg.includes('ERR_CONNECTION_REFUSED')) {
              diagnosis = 'Connection refused';
            } else if (msg.includes('ERR_EMPTY_RESPONSE')) {
              diagnosis = 'Empty response';
            } else {
              diagnosis = msg.split('\n')[0].replace('page.goto: ', '');
            }
          }

          // 2. Fallback attempt: Playwright request GET as a lightweight backup
          if (!firstAttemptOk) {
            try {
              const response = await page.request.get(url, {
                headers: {
                  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
                  'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                  'Accept-Language': 'en-US,en;q=0.5'
                },
                timeout: 10000
              });
              duration = Date.now() - start;
              httpCode = response.status();
              status = httpCode >= 500 ? 'Down' : (httpCode >= 400 ? 'Degraded' : 'Up');
              diagnosis = httpCode >= 500 ? '5xx Server Error' : (httpCode >= 400 ? 'Client Error' : 'All systems operational (via Fallback GET)');
            } catch (fallbackErr) {
              duration = Date.now() - start;
              if (diagnosis === 'Unknown error' || diagnosis === 'timeout') {
                const fallbackMsg = fallbackErr.message || '';
                diagnosis = fallbackMsg.split('\n')[0].replace('apiRequestContext.get: ', '');
              }
            }
          }

          return {
            ok: status === 'Up',
            status: status,
            httpCode: httpCode,
            duration: duration,
            diagnosis: diagnosis
          };
        }

